#!/usr/bin/env bash
# ZONO 9.2B — apply "team-truth final acceptance" (1 commit). macOS + Linux safe.
set -euo pipefail
cd "$(dirname "$0")"
echo "→ repo: $(pwd)  · HEAD: $(git rev-parse --short HEAD)"
git rev-parse --is-inside-work-tree >/dev/null 2>&1 || { echo "not a git repo"; exit 1; }
TMP="$(mktemp)"
base64 -d > "$TMP" <<'PATCH_B64'

PATCH_B64
echo "→ applying (git am --3way)…"
if git am --3way "$TMP"; then
  rm -f "$TMP"; echo "✓ applied · HEAD: $(git rev-parse --short HEAD)"
  echo "→ pushing…"; git push origin main && echo "✓ pushed — Vercel will deploy." || echo "⚠ push failed — run 'git push origin main'."
else
  echo "⚠ git am failed — aborting cleanly."; git am --abort || true; rm -f "$TMP"; exit 1
fi
